pub struct DataSourceProbeJob {
    pub input: DataSourceProbe,
    pub source: protocol::DataSourceEntry,
    state_version: String,
    session: String,
    request_id: String,
}

type RuntimeJobKey = (String, String);
type RuntimeJobs = Arc<Mutex<HashMap<RuntimeJobKey, Arc<AtomicBool>>>>;

#[derive(Clone, Default)]
pub struct RuntimeSupervisor {
    jobs: RuntimeJobs,
}

struct PreparedStrategy {
    input: StrategyRunRequest,
    version: protocol::StrategyVersion,
    run: StrategyRun,
    observed_at: String,
}

type StrategyJobs = Arc<Mutex<HashMap<String, Arc<AtomicBool>>>>;

#[derive(Clone, Default)]
pub struct StrategySupervisor {
    jobs: StrategyJobs,
}

impl StrategySupervisor {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn stop_all(&self) {
        if let Ok(jobs) = self.jobs.lock() {
            for cancel in jobs.values() {
                cancel.store(true, Ordering::Release);
            }
        }
    }

    pub fn start(&self, engine: Arc<Mutex<ControlPlane>>, request: Value) -> Value {
        let id = request_id(&request);
        let input =
            match async_payload(request, "strategy.run").and_then(payload::<StrategyRunRequest>) {
                Ok(input) => input,
                Err(error) => return failure_reply(id, error),
            };
        let (prepared, run) = match engine.lock() {
            Ok(mut control) => match control.begin_strategy(input) {
                Ok(value) => value,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        self.spawn(engine, prepared);
        success_reply(id, json!(run), Some(run.state_version))
    }

    pub fn cancel(&self, engine: Arc<Mutex<ControlPlane>>, request: Value) -> Value {
        let id = request_id(&request);
        let input =
            match async_payload(request, "strategy.cancel").and_then(payload::<StrategyCancel>) {
                Ok(input) => input,
                Err(error) => return failure_reply(id, error),
            };
        let run_id = input.run_id.clone();
        let run = match engine.lock() {
            Ok(mut control) => match control.cancel_strategy(input) {
                Ok(run) => run,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        if let Ok(jobs) = self.jobs.lock()
            && let Some(cancel) = jobs.get(&run_id)
        {
            cancel.store(true, Ordering::Release);
        }
        success_reply(id, json!(run), Some(run.state_version))
    }

    fn spawn(&self, engine: Arc<Mutex<ControlPlane>>, prepared: PreparedStrategy) {
        let key = prepared.run.run_id.clone();
        let cancel = Arc::new(AtomicBool::new(false));
        if let Ok(mut jobs) = self.jobs.lock() {
            jobs.insert(key.clone(), cancel.clone());
        }
        let jobs = self.jobs.clone();
        thread::spawn(move || {
            let running = engine
                .lock()
                .ok()
                .and_then(|mut control| control.mark_strategy_running(&key).ok());
            if running.is_none_or(|run| run.state == StrategyRunState::Cancelled) {
                if let Ok(mut jobs) = jobs.lock() {
                    jobs.remove(&key);
                }
                return;
            }
            let outcome = strategy::execute(
                &prepared.version,
                &prepared.input,
                &prepared.run.parameters,
                &prepared.observed_at,
                Some(&cancel),
            )
            .unwrap_or_else(|error| {
                strategy::RunOutcome::Failed(StrategyFailure {
                    code: error.code,
                    reason: error.message,
                    remediation: vec!["retry_strategy_run".into()],
                })
            });
            if let Ok(mut control) = engine.lock() {
                let _ = control.finish_strategy(&prepared, outcome);
            }
            if let Ok(mut jobs) = jobs.lock() {
                jobs.remove(&key);
            }
        });
    }
}

struct PreparedBacktest {
    input: BacktestRunRequest,
    run: BacktestRun,
}

type BacktestJobs = Arc<Mutex<HashMap<String, Arc<AtomicBool>>>>;

#[derive(Clone, Default)]
pub struct BacktestSupervisor {
    jobs: BacktestJobs,
}

impl BacktestSupervisor {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn stop_all(&self) {
        if let Ok(jobs) = self.jobs.lock() {
            for cancel in jobs.values() {
                cancel.store(true, Ordering::Release);
            }
        }
    }

    pub fn start(&self, engine: Arc<Mutex<ControlPlane>>, request: Value) -> Value {
        let id = request_id(&request);
        let input =
            match async_payload(request, "backtest.run").and_then(payload::<BacktestRunRequest>) {
                Ok(input) => input,
                Err(error) => return failure_reply(id, error),
            };
        let (prepared, run) = match engine.lock() {
            Ok(mut control) => match control.begin_backtest(input) {
                Ok(value) => value,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        self.spawn(engine, prepared);
        success_reply(id, json!(run), Some(run.state_version))
    }

    pub fn cancel(&self, engine: Arc<Mutex<ControlPlane>>, request: Value) -> Value {
        let id = request_id(&request);
        let input = match async_payload(request, "backtest.cancel")
            .and_then(payload::<protocol::BacktestCancel>)
        {
            Ok(input) => input,
            Err(error) => return failure_reply(id, error),
        };
        let run_id = input.run_id.clone();
        let run = match engine.lock() {
            Ok(mut control) => match control.cancel_backtest(input) {
                Ok(run) => run,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        if let Ok(jobs) = self.jobs.lock()
            && let Some(cancel) = jobs.get(&run_id)
        {
            cancel.store(true, Ordering::Release);
        }
        success_reply(id, json!(run), Some(run.state_version))
    }

    fn spawn(&self, engine: Arc<Mutex<ControlPlane>>, prepared: PreparedBacktest) {
        let key = prepared.run.run_id.clone();
        let cancel = Arc::new(AtomicBool::new(false));
        if let Ok(mut jobs) = self.jobs.lock() {
            jobs.insert(key.clone(), cancel.clone());
        }
        let jobs = self.jobs.clone();
        thread::spawn(move || {
            let running = engine
                .lock()
                .ok()
                .and_then(|mut control| control.mark_backtest_running(&key).ok());
            if running.is_none_or(|run| run.state == BacktestRunState::Cancelled) {
                if let Ok(mut jobs) = jobs.lock() {
                    jobs.remove(&key);
                }
                return;
            }
            let outcome = backtest::execute(&prepared.input, &prepared.run, Some(&cancel));
            if let Ok(mut control) = engine.lock() {
                let _ = control.finish_backtest(&prepared, outcome);
            }
            if let Ok(mut jobs) = jobs.lock() {
                jobs.remove(&key);
            }
        });
    }
}

impl RuntimeSupervisor {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn stop_all(&self) {
        if let Ok(jobs) = self.jobs.lock() {
            for cancel in jobs.values() {
                cancel.store(true, Ordering::Release);
            }
        }
    }

    pub fn start(
        &self,
        engine: Arc<Mutex<ControlPlane>>,
        request: Value,
        runtime_access: Option<codex_runtime::RuntimeAccess>,
    ) -> Value {
        let id = request_id(&request);
        let payload = match async_payload(request, "turn.start").and_then(payload::<TurnStart>) {
            Ok(input) => input,
            Err(error) => return failure_reply(id, error),
        };
        let (prepared, thread) = match engine.lock() {
            Ok(mut control) => match control.begin_turn(payload) {
                Ok(value) => value,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        self.spawn(engine, prepared, runtime_access);
        success_reply(id, json!(thread), Some(thread.state_version))
    }

    pub fn cancel(&self, engine: Arc<Mutex<ControlPlane>>, request: Value) -> Value {
        let id = request_id(&request);
        let input = match async_payload(request, "turn.cancel").and_then(payload::<TurnCancel>) {
            Ok(input) => input,
            Err(error) => return failure_reply(id, error),
        };
        let thread = match engine.lock() {
            Ok(mut control) => match control.request_turn_cancel(&input) {
                Ok(thread) => thread,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        let key = (input.thread_id.clone(), input.turn_id.clone());
        if let Ok(jobs) = self.jobs.lock() {
            if let Some(cancel) = jobs.get(&key) {
                cancel.store(true, Ordering::Release);
            } else if let Ok(mut control) = engine.lock() {
                let _ = control.interrupt_unmanaged_turn(&input.thread_id, &input.turn_id);
            }
        }
        success_reply(id, json!(thread), Some(thread.state_version))
    }

    pub fn retry(
        &self,
        engine: Arc<Mutex<ControlPlane>>,
        request: Value,
        runtime_access: Option<codex_runtime::RuntimeAccess>,
    ) -> Value {
        let id = request_id(&request);
        let input = match async_payload(request, "turn.retry").and_then(payload::<TurnRetry>) {
            Ok(input) => input,
            Err(error) => return failure_reply(id, error),
        };
        let (prepared, thread) = match engine.lock() {
            Ok(mut control) => match control.begin_retry(input) {
                Ok(value) => value,
                Err(error) => return failure_reply(id, error),
            },
            Err(_) => return failure_reply(id, TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE")),
        };
        self.spawn(engine, prepared, runtime_access);
        success_reply(id, json!(thread), Some(thread.state_version))
    }

    fn spawn(
        &self,
        engine: Arc<Mutex<ControlPlane>>,
        prepared: PreparedTurn,
        runtime_access: Option<codex_runtime::RuntimeAccess>,
    ) {
        let key = (prepared.thread_id.clone(), prepared.turn_id.clone());
        let cancel = Arc::new(AtomicBool::new(false));
        if let Ok(mut jobs) = self.jobs.lock() {
            jobs.insert(key.clone(), cancel.clone());
        }
        let jobs = self.jobs.clone();
        thread::spawn(move || {
            let mut seen = HashSet::new();
            let result = codex_runtime::run_cancellable(
                &prepared.runtime_request,
                runtime_access.as_ref(),
                &cancel,
                &mut |event| {
                    if !seen.insert(runtime_event_key(&event)) {
                        return Ok(());
                    }
                    let mut control = engine
                        .lock()
                        .map_err(|_| TradeXError::new("IPC_CONTROL_PLANE_UNAVAILABLE"))?;
                    control.apply_runtime_event(&prepared.thread_id, &prepared.turn_id, event)
                },
            );
            if let Ok(mut control) = engine.lock() {
                let _ = control.finish_runtime_turn(&prepared, result);
            }
            if let Ok(mut jobs) = jobs.lock() {
                jobs.remove(&key);
            }
        });
    }
}

fn request_id(value: &Value) -> String {
    value
        .get("requestId")
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty() && id.len() <= 128)
        .unwrap_or("invalid-request")
        .to_owned()
}

fn async_payload(value: Value, command: &str) -> Result<Value> {
    match value.get("schemaVersion").and_then(Value::as_u64) {
        Some(1) => (),
        Some(_) => return Err(TradeXError::new("IPC_SCHEMA_UNSUPPORTED")),
        None => return Err(TradeXError::new("IPC_PAYLOAD_INVALID")),
    }
    let request: CommandEnvelope = payload(value)?;
    if request.request_id.is_empty() || request.request_id.len() > 128 || request.command != command
    {
        return Err(TradeXError::new("IPC_PAYLOAD_INVALID"));
    }
    Ok(request.payload)
}

fn success_reply(id: String, data: Value, version: Option<String>) -> Value {
    let mut reply = json!({"requestId":id,"schemaVersion":1,"ok":true,"data":data});
    if let Some(version) = version {
        reply["stateVersion"] = version.into();
    }
    reply
}

fn failure_reply(id: String, error: TradeXError) -> Value {
    json!({"requestId":id,"schemaVersion":1,"ok":false,"error":error})
}

#[cfg(feature = "integration-test")]
fn browser_fixture_dispatch(
    control: &mut ControlPlane,
    command: &str,
    payload: Value,
) -> Result<Value> {
    let result = control.dispatch(json!({
        "requestId":uuid::Uuid::new_v4().to_string(),
        "schemaVersion":1,
        "command":command,
        "payload":payload
    }));
    if result["ok"] == true {
        Ok(result["data"].clone())
    } else {
        let code = result["error"]["code"]
            .as_str()
            .unwrap_or("IPC_CONTROL_PLANE_UNAVAILABLE")
            .to_owned();
        Err(TradeXError::new(&code))
    }
}

fn valid_bounded_text(value: &str, max: usize) -> bool {
    !value.is_empty() && value.len() <= max && !value.chars().any(char::is_control)
}

fn provider_order_consumer_allowed(consumer: &str) -> bool {
    consumer == "main" || (cfg!(feature = "integration-test") && consumer == "stdio")
}

fn live_provider_id(environment: &protocol::ExecutionContext) -> Option<&'static str> {
    match environment {
        protocol::ExecutionContext::Trading212Live => Some("trading212"),
        protocol::ExecutionContext::BinanceLive => Some("binance"),
        protocol::ExecutionContext::BitgetLive => Some("bitget"),
        _ => None,
    }
}

fn live_reconciliation_provider(environment: &protocol::ExecutionContext) -> Option<&'static str> {
    match environment {
        protocol::ExecutionContext::Trading212Live => Some("trading212"),
        protocol::ExecutionContext::BinanceLive => Some("binance"),
        protocol::ExecutionContext::BitgetLive => Some("bitget"),
        _ => None,
    }
}

fn expected_live_provider_client_order_id(
    attempt: &protocol::ExecutionAttempt,
) -> Result<Option<String>> {
    match live_reconciliation_provider(&attempt.environment) {
        Some("binance") => provider_io::binance_live_client_order_id(&attempt.attempt_id).map(Some),
        Some("bitget") => provider_io::bitget_live_client_order_id(&attempt.attempt_id).map(Some),
        Some("trading212") => Ok(None),
        _ => Err(TradeXError::new("STATE_VERSION_CONFLICT")),
    }
}

fn live_place_reconciliation_window(
    attempt: &protocol::ExecutionAttempt,
) -> Result<(String, String)> {
    // Legacy UNKNOWN attempts predate this field; their preparation time gives a conservative, earlier cutoff.
    let started_at = attempt
        .dispatch_started_at
        .as_deref()
        .unwrap_or(&attempt.created_at);
    let started = OffsetDateTime::parse(started_at, &Rfc3339)
        .map_err(|_| TradeXError::new("WORKSPACE_INTEGRITY_FAILED"))?;
    let created = OffsetDateTime::parse(&attempt.created_at, &Rfc3339)
        .map_err(|_| TradeXError::new("WORKSPACE_INTEGRITY_FAILED"))?;
    let ends = started
        .checked_add(TimeDuration::minutes(5))
        .ok_or_else(|| TradeXError::new("WORKSPACE_INTEGRITY_FAILED"))?;
    if started < created {
        return Err(TradeXError::new("WORKSPACE_INTEGRITY_FAILED"));
    }
    Ok((
        started
            .format(&Rfc3339)
            .map_err(|_| TradeXError::new("WORKSPACE_INTEGRITY_FAILED"))?,
        ends.format(&Rfc3339)
            .map_err(|_| TradeXError::new("WORKSPACE_INTEGRITY_FAILED"))?,
    ))
}

struct LivePlaceCapacity {
    capacity_key: String,
    amount: String,
    projection: protocol::CapacityProjection,
}

fn capacity_evidence_freshness(
    account: &AccountConnection,
    now: &str,
) -> protocol::CapacityFreshness {
    let data = account.data.as_ref();
    let Some(data) = data else {
        return protocol::CapacityFreshness::Unavailable;
    };
    let observed = account
        .last_successful_sync
        .as_deref()
        .and_then(|value| OffsetDateTime::parse(value, &Rfc3339).ok());
    let now_time = OffsetDateTime::parse(now, &Rfc3339).ok();
    let (Some(observed), Some(now_time)) = (observed, now_time) else {
        return protocol::CapacityFreshness::Unavailable;
    };
    if now_time < observed {
        return protocol::CapacityFreshness::Unavailable;
    }
    if now_time - observed > ::time::Duration::seconds(30)
        || account.health.reconciliation != "CURRENT"
    {
        return protocol::CapacityFreshness::Stale;
    }
    if !["account.read", "positions.read", "orders.read"]
        .iter()
        .all(|required| {
            data.capabilities
                .iter()
                .any(|capability| capability == required)
        })
    {
        return protocol::CapacityFreshness::Unavailable;
    }
    protocol::CapacityFreshness::Current
}

fn unavailable_capacity_projection(
    proposal: &protocol::OrderProposal,
    account: &AccountConnection,
    market: &protocol::MarketDetail,
    maximum_authorized_spend: Option<&str>,
    freshness: protocol::CapacityFreshness,
) -> protocol::CapacityProjection {
    let trading212_sell =
        account.provider_id == "trading212" && proposal.fields.side == protocol::OrderSide::Sell;
    let unit = if proposal.fields.side == protocol::OrderSide::Buy {
        market.instrument.currency.clone()
    } else if trading212_sell {
        market.instrument.symbol.clone()
    } else {
        market
            .instrument
            .base
            .clone()
            .unwrap_or_else(|| market.instrument.symbol.clone())
    };
    let (available_source, committed_source) = if trading212_sell {
        (
            protocol::CapacityAvailableSource::PositionLessOpenSellOrders,
            protocol::CapacityCommittedSource::OpenSellOrders,
        )
    } else {
        (
            protocol::CapacityAvailableSource::ProviderBalanceAvailable,
            protocol::CapacityCommittedSource::ProviderBalanceCommitted,
        )
    };
    protocol::CapacityProjection {
        account_state_version: account.state_version.clone(),
        available: None,
        committed: None,
        reserved: None,
        effective_available: None,
        unit,
        available_source,
        committed_source,
        freshness,
        observed_at: account.last_successful_sync.clone(),
        requested_amount: if proposal.fields.side == protocol::OrderSide::Buy {
            maximum_authorized_spend.map(str::to_owned)
        } else {
            Some(proposal.fields.quantity.value.clone())
        },
    }
}

fn live_place_capacity(
    proposal: &protocol::OrderProposal,
    account: &AccountConnection,
    market: &protocol::MarketDetail,
    maximum_authorized_spend: Option<&str>,
    now: &str,
) -> Result<LivePlaceCapacity> {
    if capacity_evidence_freshness(account, now) != protocol::CapacityFreshness::Current {
        return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
    }
    let data = account
        .data
        .as_ref()
        .ok_or_else(|| TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"))?;
    let instrument = &market.instrument;
    let quote_currency = instrument.currency.as_str();
    if quote_currency.len() < 2
        || quote_currency.len() > 16
        || !quote_currency
            .bytes()
            .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit())
    {
        return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
    }
    let (capacity_key, amount, unit, available, committed, available_source, committed_source) =
        match proposal.fields.side {
            protocol::OrderSide::Buy => {
                let amount = maximum_authorized_spend
                    .ok_or_else(|| TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"))?;
                if crate::provider_io::decimal_cmp(amount, "0")? != std::cmp::Ordering::Greater {
                    return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                }
                let balances = data
                    .balances
                    .iter()
                    .filter(|balance| balance.asset.eq_ignore_ascii_case(quote_currency))
                    .collect::<Vec<_>>();
                if balances.len() != 1 {
                    return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                }
                // Provider adapters expose free/available-to-trade cash after broker order locks.
                // Subtracting those same orders again would double-count committed capacity.
                let available = crate::provider_io::decimal(&serde_json::Value::String(
                    balances[0].available.clone(),
                ))?;
                let committed = if account.provider_id == "trading212" {
                    balances[0]
                        .reserved
                        .as_deref()
                        .map(|value| {
                            crate::provider_io::decimal(&serde_json::Value::String(value.into()))
                        })
                        .transpose()?
                } else {
                    balances[0]
                        .total
                        .as_deref()
                        .map(|total| {
                            let total = crate::provider_io::decimal(&serde_json::Value::String(
                                total.into(),
                            ))?;
                            if crate::provider_io::decimal_cmp(&total, &available)?
                                == std::cmp::Ordering::Less
                            {
                                return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                            }
                            crate::provider_io::decimal_subtract(&total, &available)
                        })
                        .transpose()?
                };
                let committed_source = if committed.is_some() {
                    protocol::CapacityCommittedSource::ProviderBalanceCommitted
                } else {
                    protocol::CapacityCommittedSource::Unavailable
                };
                (
                    format!("cash:{quote_currency}"),
                    amount.to_owned(),
                    quote_currency.to_owned(),
                    available,
                    committed,
                    protocol::CapacityAvailableSource::ProviderBalanceAvailable,
                    committed_source,
                )
            }
            protocol::OrderSide::Sell => {
                if proposal.fields.quantity.r#type != protocol::OrderQuantityType::Base {
                    return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                }
                let amount = crate::provider_io::decimal(&serde_json::Value::String(
                    proposal.fields.quantity.value.clone(),
                ))?;
                if crate::provider_io::decimal_cmp(&amount, "0")? != std::cmp::Ordering::Greater {
                    return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                }
                if account.provider_id == "trading212" {
                    let positions = data
                        .positions
                        .iter()
                        .filter(|position| {
                            position.instrument_id.as_deref()
                                == Some(instrument.instrument_id.as_str())
                                || position.symbol == instrument.symbol
                        })
                        .collect::<Vec<_>>();
                    if positions.len() != 1 {
                        return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                    }
                    let mut available = crate::provider_io::decimal(&serde_json::Value::String(
                        positions[0].quantity.clone(),
                    ))?;
                    let mut committed = "0".to_owned();
                    for order in data.open_orders.iter().filter(|order| {
                        order.side.eq_ignore_ascii_case("SELL")
                            && order.symbol == instrument.symbol
                            && matches!(
                                order.status.as_str(),
                                "LOCAL"
                                    | "UNCONFIRMED"
                                    | "CONFIRMED"
                                    | "NEW"
                                    | "CANCELLING"
                                    | "PARTIALLY_FILLED"
                                    | "REPLACING"
                            )
                    }) {
                        let quantity = order
                            .quantity
                            .as_deref()
                            .ok_or_else(|| TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"))?;
                        let filled = order
                            .filled_quantity
                            .as_deref()
                            .ok_or_else(|| TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"))?;
                        let remaining = crate::provider_io::decimal_subtract(quantity, filled)?;
                        committed = crate::portfolio::decimal_add(&committed, &remaining)?;
                        available = crate::provider_io::decimal_subtract(&available, &remaining)?;
                    }
                    if crate::provider_io::decimal_cmp(&available, "0")? == std::cmp::Ordering::Less
                    {
                        return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                    }
                    (
                        format!("asset:{}", instrument.symbol),
                        amount,
                        instrument.symbol.clone(),
                        available,
                        Some(committed),
                        protocol::CapacityAvailableSource::PositionLessOpenSellOrders,
                        protocol::CapacityCommittedSource::OpenSellOrders,
                    )
                } else {
                    let base = instrument
                        .base
                        .as_deref()
                        .ok_or_else(|| TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"))?;
                    let balances = data
                        .balances
                        .iter()
                        .filter(|balance| balance.asset.eq_ignore_ascii_case(base))
                        .collect::<Vec<_>>();
                    if balances.len() != 1 {
                        return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                    }
                    let available = crate::provider_io::decimal(&serde_json::Value::String(
                        balances[0].available.clone(),
                    ))?;
                    let committed = balances[0]
                        .total
                        .as_deref()
                        .map(|total| {
                            let total = crate::provider_io::decimal(&serde_json::Value::String(
                                total.into(),
                            ))?;
                            if crate::provider_io::decimal_cmp(&total, &available)?
                                == std::cmp::Ordering::Less
                            {
                                return Err(TradeXError::new("RISK_EVIDENCE_UNAVAILABLE"));
                            }
                            crate::provider_io::decimal_subtract(&total, &available)
                        })
                        .transpose()?;
                    let committed_source = if committed.is_some() {
                        protocol::CapacityCommittedSource::ProviderBalanceCommitted
                    } else {
                        protocol::CapacityCommittedSource::Unavailable
                    };
                    (
                        format!("asset:{base}"),
                        amount,
                        base.to_owned(),
                        available,
                        committed,
                        protocol::CapacityAvailableSource::ProviderBalanceAvailable,
                        committed_source,
                    )
                }
            }
        };
    let projection = protocol::CapacityProjection {
        account_state_version: account.state_version.clone(),
        available: Some(available.clone()),
        committed,
        reserved: Some("0".into()),
        effective_available: Some(available),
        unit,
        available_source,
        committed_source,
        freshness: protocol::CapacityFreshness::Current,
        observed_at: account.last_successful_sync.clone(),
        requested_amount: Some(amount.clone()),
    };
    Ok(LivePlaceCapacity {
        capacity_key,
        amount,
        projection,
    })
}

fn proposal_value(
    proposal: &protocol::OrderProposal,
    market: Option<&protocol::MarketDetail>,
) -> Option<String> {
    use protocol::{OrderQuantityType, OrderSide, OrderType};
    if proposal.fields.quantity.r#type == OrderQuantityType::Quote {
        return Some(proposal.fields.quantity.value.clone());
    }
    let price = match (proposal.fields.order_type, proposal.fields.side) {
        (OrderType::Limit, _) => proposal.fields.limit_price.as_deref(),
        (OrderType::Market, OrderSide::Buy) => market
            .and_then(|market| market.snapshot.as_ref())
            .and_then(|snapshot| snapshot.ask.as_deref()),
        (OrderType::Market, OrderSide::Sell) => market
            .and_then(|market| market.snapshot.as_ref())
            .and_then(|snapshot| snapshot.bid.as_deref()),
    }?;
    crate::portfolio::decimal_mul(price, &proposal.fields.quantity.value).ok()
}

fn quote_age_ms(
    time_status: &protocol::TimeStatus,
    market: Option<&protocol::MarketDetail>,
) -> Option<u64> {
    let received = market?
        .snapshot
        .as_ref()?
        .provenance
        .received_timestamp
        .as_str();
    let now = OffsetDateTime::parse(&time_status.wall_clock, &Rfc3339).ok()?;
    let received = OffsetDateTime::parse(received, &Rfc3339).ok()?;
    u64::try_from((now - received).whole_milliseconds()).ok()
}

fn is_approval_bound_risk_input(input: &&risk::RiskDecisionInputReference) -> bool {
    input.kind != risk::RiskDecisionInputKind::Reservations
}

fn is_approval_bound_risk_check(check: &&risk::RiskCheckResult) -> bool {
    check.check_id != risk::RiskCheckId::ReservedCapital
}

fn approval_review_digest(
    proposal: &protocol::OrderProposal,
    account: Option<&AccountConnection>,
    market: Option<&protocol::MarketDetail>,
    policy: Option<&risk::RiskPolicyState>,
    bound_decision: &risk::RiskDecision,
    current_decision: &risk::RiskDecision,
    time_status: &protocol::TimeStatus,
) -> Result<String> {
    let mut market =
        serde_json::to_value(market).map_err(|_| TradeXError::new("IPC_PAYLOAD_INVALID"))?;
    // Observation times advance during reads; the quote's provider and receipt timestamps are
    // material review data and remain bound after canonicalization.
    if let Some(state) = market
        .get_mut("instrumentState")
        .and_then(Value::as_object_mut)
    {
        state.remove("observedAt");
    }
    if let Some(state) = market.get_mut("marketState").and_then(Value::as_object_mut) {
        state.remove("observedAt");
        risk::canonicalize_timestamp_field(state.get_mut("providerTime"));
    }
    if let Some(provenance) = market
        .get_mut("snapshot")
        .and_then(Value::as_object_mut)
        .and_then(|snapshot| snapshot.get_mut("provenance"))
        .and_then(Value::as_object_mut)
    {
        risk::canonicalize_timestamp_field(provenance.get_mut("providerTimestamp"));
        risk::canonicalize_timestamp_field(provenance.get_mut("receivedTimestamp"));
    }
    let bound_checks = bound_decision
        .checks
        .iter()
        .filter(is_approval_bound_risk_check)
        .collect::<Vec<_>>();
    let current_checks = current_decision
        .checks
        .iter()
        .filter(is_approval_bound_risk_check)
        .collect::<Vec<_>>();
    let material = json!({
        "proposal": {
            "workspaceId": proposal.workspace_id,
            "proposalId": proposal.proposal_id,
            "proposalHash": proposal.proposal_hash,
            "stateVersion": proposal.state_version,
            "fields": proposal.fields,
            "policyVersion": proposal.policy_version,
            "policyStateVersion": proposal.policy_state_version,
            "policyStatus": proposal.policy_status,
            "marketSnapshotId": proposal.market_snapshot_id,
            "status": proposal.status,
        },
        "account": account,
        "policy": policy,
        "market": market,
        "boundRiskDecision": {
            "decisionId": bound_decision.decision_id,
            "proposalHash": bound_decision.proposal_hash,
            "accountId": bound_decision.account_id,
            "environment": bound_decision.environment,
            "policyVersion": bound_decision.policy_version,
            "status": bound_decision.status,
            "checks": bound_checks,
            "inputs": bound_decision.inputs.iter().filter(is_approval_bound_risk_input).map(|input| json!({
                "kind": input.kind,
                "digest": input.digest,
            })).collect::<Vec<_>>(),
        },
        "currentRiskChecks": {
            "status": bound_decision.status,
            "checks": current_checks,
            "inputs": current_decision.inputs.iter().filter(is_approval_bound_risk_input).map(|input| json!({
                "kind": input.kind,
                "digest": input.digest,
            })).collect::<Vec<_>>(),
        },
        "time": {
            "confidence": time_status.confidence,
            "providerOffsetMs": time_status.provider_offset_ms,
        },
    });
    let bytes =
        serde_json::to_vec(&material).map_err(|_| TradeXError::new("IPC_PAYLOAD_INVALID"))?;
    Ok(format!("sha256:{}", hex::encode(Sha256::digest(bytes))))
}

fn cancellation_intent_from_account(
    account: &AccountConnection,
    broker_order_id: &str,
    previous: Option<&protocol::CancellationIntent>,
    observed_at: &str,
) -> Result<protocol::CancellationIntent> {
    let environment = match account.provider_id.as_str() {
        "trading212" if account.environment == "LIVE" => protocol::ExecutionContext::Trading212Live,
        "binance" if account.environment == "LIVE" => protocol::ExecutionContext::BinanceLive,
        "bitget" if account.environment == "LIVE" => protocol::ExecutionContext::BitgetLive,
        _ => return Err(TradeXError::new("PROVIDER_LIVE_UNSUPPORTED")),
    };
    let order = account
        .data
        .as_ref()
        .and_then(|data| {
            data.open_orders
                .iter()
                .find(|order| order.broker_order_id == broker_order_id)
        })
        .ok_or_else(|| TradeXError::new("ORDER_NOT_CANCELLABLE"))?;
    let status = order.status.to_ascii_uppercase();
    let cancellable = match account.provider_id.as_str() {
        "trading212" => matches!(
            status.as_str(),
            "UNCONFIRMED" | "CONFIRMED" | "NEW" | "PARTIALLY_FILLED"
        ),
        "binance" => matches!(status.as_str(), "NEW" | "PENDING_NEW" | "PARTIALLY_FILLED"),
        "bitget" => {
            order.kind.as_deref() == Some("NORMAL")
                && matches!(status.as_str(), "NEW" | "LIVE" | "PARTIALLY_FILLED")
        }
        _ => false,
    };
    if !cancellable {
        return Err(TradeXError::new("ORDER_NOT_CANCELLABLE"));
    }
    let quantity = order
        .quantity
        .as_deref()
        .ok_or_else(|| TradeXError::new("ORDER_NOT_CANCELLABLE"))?;
    let filled = order
        .filled_quantity
        .as_deref()
        .ok_or_else(|| TradeXError::new("ORDER_NOT_CANCELLABLE"))?;
    let instrument_id = order
        .instrument_id
        .as_deref()
        .ok_or_else(|| TradeXError::new("ORDER_NOT_CANCELLABLE"))?;
    let quantity = provider_io::decimal(&Value::String(quantity.into()))?;
    let filled = provider_io::decimal(&Value::String(filled.into()))?;
    let (quantity, filled) = if account.provider_id == "trading212" {
        (
            provider_io::decimal_magnitude(&quantity)?,
            provider_io::decimal_magnitude(&filled)?,
        )
    } else {
        (quantity, filled)
    };
    let remaining = provider_io::decimal_subtract(&quantity, &filled)?;
    if remaining == "0" {
        return Err(TradeXError::new("ORDER_NOT_CANCELLABLE"));
    }
    let mut intent = protocol::CancellationIntent {
        cancellation_intent_id: previous
            .map(|intent| intent.cancellation_intent_id.clone())
            .unwrap_or_else(|| format!("cancel:{}", uuid::Uuid::new_v4())),
        intent_hash: String::new(),
        workspace_id: account.workspace_id.clone(),
        account_id: account.connection_id.clone(),
        environment,
        provider_order_id: order.broker_order_id.clone(),
        instrument_id: instrument_id.into(),
        symbol: order.symbol.clone(),
        side: order.side.to_ascii_uppercase(),
        provider_status: status,
        quantity,
        filled_quantity: filled,
        remaining_quantity: remaining,
        created_at: previous
            .map(|intent| intent.created_at.clone())
            .unwrap_or_else(|| observed_at.into()),
    };
    intent.intent_hash = storage::cancellation_intent_hash(&intent)?;
    Ok(intent)
}

