    #[cfg(feature = "integration-test")]
    pub fn seed_browser_model_gateway(
        &mut self,
        workspace_id: &str,
        status: gateway::GatewayStatus,
    ) -> Result<()> {
        self.require_workspace(workspace_id)?;
        let error_code = match status {
            gateway::GatewayStatus::Stopped => Some("MODEL_UNAVAILABLE"),
            gateway::GatewayStatus::Unauthorized => Some("GATEWAY_UNAUTHORIZED"),
            gateway::GatewayStatus::PortConflict => Some("GATEWAY_PORT_CONFLICT"),
            gateway::GatewayStatus::Running => None,
            _ => return Err(TradeXError::new("IPC_PAYLOAD_INVALID")),
        };
        // Disposable browser fixture: no sidecar is launched or stopped.
        let mut state = self.store.as_ref().unwrap().gateway()?;
        state.status = status;
        state.model_available = error_code.is_none();
        state.error_code = error_code.map(str::to_owned);
        let event = self.store.as_mut().unwrap().save_gateway(state)?;
        self.publish(&event);
        Ok(())
    }

    #[cfg(feature = "integration-test")]
    pub fn seed_browser_workspace_ready(&mut self, workspace_id: &str) -> Result<()> {
        self.require_workspace(workspace_id)?;
        {
            let store = self.store.as_mut().unwrap();
            let mut model = store.model()?;
            let route = model::ModelRoute {
                provider: model::ModelProvider::Chatgpt,
                model_id: "gpt-5.6-sol".into(),
                thinking_type: None,
                verified_at: Some("2026-09-24T00:00:00Z".into()),
            };
            model.chatgpt.configured = true;
            model.chatgpt.status = model::ModelHealth::Ready;
            model.chatgpt.routes = vec![route.clone()];
            model.default_route = Some(route.selection());
            model.current_route = Some(route);
            store.save_model(model, "model.provider.changed")?;

            let mut gateway = store.gateway()?;
            gateway.status = gateway::GatewayStatus::Running;
            gateway.desired_running = true;
            gateway.installed = true;
            gateway.model_available = true;
            gateway.discovered_model_count = 1;
            store.save_gateway(gateway)?;
        }

        let mut risk =
            browser_fixture_dispatch(self, "risk.get_policy", json!({"workspaceId":workspace_id}))?;
        if risk["onboardingCompleted"] == true {
            return Ok(());
        }
        let mut step = risk["onboardingStep"].as_u64().unwrap_or(1) as u8;
        let mut version = risk["stateVersion"].as_str().unwrap_or_default().to_owned();
        while step < 4 {
            step += 1;
            risk = browser_fixture_dispatch(
                self,
                "onboarding.set_step",
                json!({"workspaceId":workspace_id,"expectedStateVersion":version,"step":step}),
            )?;
            version = risk["stateVersion"].as_str().unwrap_or_default().to_owned();
        }
        if risk["configured"] != true {
            risk = browser_fixture_dispatch(
                self,
                "risk.save_policy",
                json!({
                    "workspaceId":workspace_id,
                    "expectedStateVersion":version,
                    "policy":{
                        "maxOrderNotional":null,
                        "maxOrderQuantity":null,
                        "maxPositionSize":null,
                        "maxSingleInstrumentExposurePercent":"10.25",
                        "maxAssetClassExposurePercent":[],
                        "maxDailyTradedNotional":null,
                        "maxDailyRealizedLoss":null,
                        "maxOpenOrders":null,
                        "maxReservedCapital":null,
                        "allowedInstrumentIds":[],
                        "blockedInstrumentIds":[],
                        "allowedVenues":[],
                        "blockedVenues":[],
                        "allowedAccountIds":[],
                        "blockedAccountIds":[],
                        "allowedEnvironments":[],
                        "staleQuoteThresholdSeconds":3,
                        "marketOrdersEnabled":false,
                        "maxMarketOrderSlippagePercent":null,
                        "maxPriceDeviationPercent":null,
                        "liveInactivityTimeoutMinutes":20
                    }
                }),
            )?;
            version = risk["stateVersion"].as_str().unwrap_or_default().to_owned();
        }
        risk = browser_fixture_dispatch(
            self,
            "onboarding.set_step",
            json!({"workspaceId":workspace_id,"expectedStateVersion":version,"step":5}),
        )?;
        browser_fixture_dispatch(
            self,
            "onboarding.complete",
            json!({"workspaceId":workspace_id,"expectedStateVersion":risk["stateVersion"]}),
        )?;
        Ok(())
    }

    fn prepare_trading212_demo_order_submit(
        &mut self,
        request: CommandEnvelope,
        consumer: &str,
    ) -> Result<Option<ProviderJob>> {
        if !provider_order_consumer_allowed(consumer) {
            return Err(TradeXError::new("ORDER_SUBMIT_FORBIDDEN"));
        }
        let input: Trading212DemoOrderSubmit = payload(request.payload)?;
        self.require_workspace(&input.workspace_id)?;
        if let Some(existing) = self
            .store
            .as_ref()
            .unwrap()
            .trading212_demo_order_attempt(&input.workspace_id, &input.proposal_id)?
        {
            if existing.connection_id != input.connection_id
                || existing.proposal_hash != input.proposal_hash
            {
                return Err(TradeXError::new("STATE_VERSION_CONFLICT"));
            }
            return Ok(None);
        }
        let account = self.current_account(
            &input.workspace_id,
            &input.connection_id,
            &input.expected_connection_state_version,
        )?;
        if account.provider_id != "trading212" || account.environment != "DEMO" {
            return Err(TradeXError::new("PROVIDER_UNSUPPORTED"));
        }
        let proposal = self
            .store
            .as_ref()
            .unwrap()
            .order_proposal(&input.proposal_id)?;
        if proposal.workspace_id != input.workspace_id
            || proposal.proposal_hash != input.proposal_hash
        {
            return Err(TradeXError::new("STATE_VERSION_CONFLICT"));
        }
        if proposal.state_version != input.expected_proposal_state_version {
            return Err(TradeXError::new("STATE_VERSION_CONFLICT"));
        }
        provider_io::validate_trading212_demo_proposal(&proposal, &input.connection_id)?;
        self.require_risk_allowed(&input.workspace_id, &input.proposal_id)?;
        let (attempt, created) = self
            .store
            .as_mut()
            .unwrap()
            .begin_trading212_demo_order_attempt(&input)?;
        if !created {
            return Ok(None);
        }
        Ok(Some(ProviderJob {
            account,
            kind: JobKind::Trading212DemoSubmit,
            session: self.session.clone(),
            request_id: request.request_id,
            trading212_demo_attempt: Some(attempt),
            trading212_demo_proposal: Some(proposal),
            trading212_demo_order_book: None,
            trading212_demo_order_id: None,
            alpaca_attempt: None,
            alpaca_proposal: None,
            alpaca_order_book: None,
            alpaca_order_id: None,
            alpaca_expected_order: None,
            binance_testnet_attempt: None,
            binance_testnet_proposal: None,
            binance_testnet_order_book: None,
            binance_testnet_book_action: None,
            binance_testnet_book_symbol: None,
            binance_testnet_book_order_id: None,
            bitget_demo_attempt: None,
            bitget_demo_proposal: None,
        }))
    }

