    pub(super) fn approval_action(workspace_id: &str, proposal: &Value, review: &Value) -> Value {
        json!({
            "workspaceId": workspace_id,
            "proposalId": proposal["proposalId"],
            "proposalHash": proposal["proposalHash"],
            "reviewedRiskDecisionId": review["riskDecision"]["decisionId"],
            "reviewDigest": review["reviewDigest"],
            "expectedStateVersion": proposal["stateVersion"],
        })
    }

    pub(super) fn issue_and_prepare_live_place(
        control: &mut ControlPlane,
        workspace_id: &str,
        proposal: &Value,
        review: &Value,
        idempotency_key: &str,
    ) -> (Value, Value, Value) {
        let approval = dispatch_main(
            control,
            "trade.approve",
            approval_action(workspace_id, proposal, review),
        );
        assert_eq!(approval["ok"], true, "{approval}");
        let prepare = json!({
            "workspaceId": workspace_id,
            "approvalId": approval["data"]["approvalId"],
            "expectedApprovalStateVersion": approval["data"]["stateVersion"],
            "idempotencyKey": idempotency_key,
            "confirmed": true,
        });
        let prepared = dispatch_main(control, "trade.execution.prepare", prepare.clone());
        assert_eq!(prepared["ok"], true, "{prepared}");
        (approval, prepare, prepared)
    }

