    struct BitgetLiveResolutionHttp {
        remote_account_id: String,
        order: std::cell::RefCell<Option<Value>>,
        order_error_code: std::cell::RefCell<Option<String>>,
        order_transport_error: std::cell::Cell<bool>,
        calls: std::cell::RefCell<
            Vec<(
                provider_io::ProviderEndpoint,
                provider_io::ProviderHttpMethod,
                String,
            )>,
        >,
        writes: std::cell::Cell<usize>,
    }

    impl BitgetLiveResolutionHttp {
        fn response(
            &self,
            endpoint: provider_io::ProviderEndpoint,
            method: provider_io::ProviderHttpMethod,
            path: &str,
            headers: reqwest::header::HeaderMap,
        ) -> Result<provider_io::ProviderHttpResponse> {
            use hmac::Mac;
            self.calls
                .borrow_mut()
                .push((endpoint, method, path.into()));
            if endpoint != provider_io::ProviderEndpoint::BitgetLive
                || method != provider_io::ProviderHttpMethod::Get
            {
                self.writes.set(self.writes.get() + 1);
                return Err(TradeXError::new("PROVIDER_UNSUPPORTED"));
            }
            if path.starts_with("/api/v2/spot/trade/orderInfo?") && self.order_transport_error.get()
            {
                return Err(TradeXError::new("PROVIDER_UNAVAILABLE"));
            }
            let body = if path == "/api/v2/public/time" {
                assert!(headers.is_empty());
                json!({
                    "code":"00000",
                    "data":{"serverTime":(OffsetDateTime::now_utc().unix_timestamp_nanos() / 1_000_000).to_string()}
                })
            } else {
                assert!(!headers.contains_key("paptrading"));
                assert_eq!(headers["ACCESS-KEY"], "synthetic-bitget-key");
                assert_eq!(headers["ACCESS-PASSPHRASE"], "synthetic-bitget-passphrase");
                assert!(headers["ACCESS-KEY"].is_sensitive());
                assert!(headers["ACCESS-PASSPHRASE"].is_sensitive());
                assert!(headers["ACCESS-SIGN"].is_sensitive());
                let timestamp = headers["ACCESS-TIMESTAMP"].to_str().unwrap();
                let mut mac = hmac::Hmac::<sha2::Sha256>::new_from_slice(
                    "synthetic-bitget-secret".as_bytes(),
                )
                .unwrap();
                mac.update(format!("{timestamp}GET{path}").as_bytes());
                mac.verify_slice(
                    &base64::Engine::decode(
                        &base64::engine::general_purpose::STANDARD,
                        headers["ACCESS-SIGN"].as_bytes(),
                    )
                    .unwrap(),
                )
                .unwrap();
                match path {
                    "/api/v2/spot/account/info" => json!({
                        "code":"00000",
                        "data":{"userId":self.remote_account_id}
                    }),
                    _ if path.starts_with("/api/v2/spot/trade/orderInfo?clientOid=") => {
                        if let Some(code) = self.order_error_code.borrow().as_ref() {
                            json!({"code":code,"msg":"synthetic auth failure","data":[]})
                        } else {
                            let client_oid = path
                                .strip_prefix("/api/v2/spot/trade/orderInfo?clientOid=")
                                .unwrap();
                            let rows = self
                                .order
                                .borrow()
                                .as_ref()
                                .filter(|order| order["clientOid"] == client_oid)
                                .cloned()
                                .into_iter()
                                .collect::<Vec<_>>();
                            json!({"code":"00000","data":rows})
                        }
                    }
                    _ => return Err(TradeXError::new("PROVIDER_UNSUPPORTED")),
                }
            };
            Ok(provider_io::ProviderHttpResponse {
                status: 200,
                body: serde_json::to_vec(&body).unwrap(),
            })
        }
    }

    impl provider_io::ProviderHttp for BitgetLiveResolutionHttp {
        fn get(
            &self,
            endpoint: provider_io::ProviderEndpoint,
            path: &str,
            headers: reqwest::header::HeaderMap,
        ) -> Result<Vec<u8>> {
            self.response(
                endpoint,
                provider_io::ProviderHttpMethod::Get,
                path,
                headers,
            )
            .map(|response| response.body)
        }

        fn request(
            &self,
            endpoint: provider_io::ProviderEndpoint,
            method: provider_io::ProviderHttpMethod,
            path: &str,
            headers: reqwest::header::HeaderMap,
            _body: Option<&Value>,
        ) -> Result<provider_io::ProviderHttpResponse> {
            self.response(endpoint, method, path, headers)
        }
    }

    struct ResolutionHttp {
        remote_account_id: String,
        order_created_at: String,
        calls: std::cell::RefCell<Vec<(String, String)>>,
    }

    impl ResolutionHttp {
        fn response(&self, method: &str, path: &str) -> Result<provider_io::ProviderHttpResponse> {
            self.calls.borrow_mut().push((method.into(), path.into()));
            if method != "GET" {
                return Err(TradeXError::new("PROVIDER_UNSUPPORTED"));
            }
            let body = match path.split('?').next().unwrap_or(path) {
                "/api/v0/equity/account/summary" => json!({
                    "id":self.remote_account_id.parse::<i64>().unwrap()
                }),
                "/api/v0/equity/orders" => json!([]),
                "/api/v0/equity/history/orders" if path.contains("cursor=123") => {
                    json!({"items":[],"nextPagePath":null})
                }
                "/api/v0/equity/history/orders" => json!({
                    "items":[{
                        "fill":{"id":1,"quantity":0,"type":"TRADE"},
                        "order":{"id":9001,"ticker":"AAPL_US_EQ","side":"BUY",
                            "type":"MARKET","timeInForce":"DAY","strategy":"QUANTITY",
                            "quantity":1,"filledQuantity":0,"filledValue":0,"currency":"USD",
                            "status":"NEW","createdAt":self.order_created_at}
                    }],
                    "nextPagePath":"/api/v0/equity/history/orders?limit=50&cursor=123&ticker=AAPL_US_EQ"
                }),
                _ => return Err(TradeXError::new("PROVIDER_UNSUPPORTED")),
            };
            Ok(provider_io::ProviderHttpResponse {
                status: 200,
                body: serde_json::to_vec(&body).unwrap(),
            })
        }
    }

    impl provider_io::ProviderHttp for ResolutionHttp {
        fn get(
            &self,
            _endpoint: provider_io::ProviderEndpoint,
            path: &str,
            _headers: reqwest::header::HeaderMap,
        ) -> Result<Vec<u8>> {
            self.response("GET", path).map(|response| response.body)
        }

        fn request(
            &self,
            _endpoint: provider_io::ProviderEndpoint,
            method: provider_io::ProviderHttpMethod,
            path: &str,
            _headers: reqwest::header::HeaderMap,
            _body: Option<&Value>,
        ) -> Result<provider_io::ProviderHttpResponse> {
            let method = match method {
                provider_io::ProviderHttpMethod::Get => "GET",
                provider_io::ProviderHttpMethod::Post => "POST",
                provider_io::ProviderHttpMethod::Delete => "DELETE",
            };
            self.response(method, path)
        }
    }

    fn make_unknown_t212_attempt(
        control: &mut ControlPlane,
        workspace_id: &str,
        proposal: &Value,
        review: &Value,
    ) -> (String, AccountConnection, String) {
        let (_, _, prepared) = issue_and_prepare_live_place(
            control,
            workspace_id,
            proposal,
            review,
            "t212-unknown-resolution",
        );
        let attempt_id = prepared["data"]["attempt"]["attemptId"]
            .as_str()
            .unwrap()
            .to_owned();
        let grant = control
            .issue_live_dispatch_grant(&attempt_id, "resolution-gateway")
            .unwrap();
        let submitting = control
            .begin_live_execution_submission(&grant.grant_id, "resolution-gateway")
            .unwrap();
        let window_started_at = submitting.dispatch_started_at.clone().unwrap();
        assert_eq!(
            control
                .complete_live_execution_submission(
                    &attempt_id,
                    &provider_io::LiveDispatchOutcome {
                        state: protocol::ExecutionAttemptState::UnknownReconciling,
                        broker_order_id: None,
                        provider_status: None,
                        error_code: Some("ORDER_STATUS_UNKNOWN".into()),
                    },
                )
                .unwrap()
                .attempt
                .state,
            protocol::ExecutionAttemptState::UnknownReconciling
        );
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(proposal["fields"]["accountId"].as_str().unwrap())
            .unwrap();
        (attempt_id, account, window_started_at)
    }

    fn make_unknown_binance_live_attempt(
        control: &mut ControlPlane,
        workspace_id: &str,
        proposal: &Value,
        review: &Value,
    ) -> (String, AccountConnection, String) {
        assert_eq!(proposal["fields"]["environment"], "BINANCE_LIVE");
        let approval = dispatch_main(
            control,
            "trade.approve",
            approval_action(workspace_id, proposal, review),
        );
        assert_eq!(approval["ok"], true, "{approval}");
        let attempt_id = uuid::Uuid::new_v4().to_string();
        let reservation_id = uuid::Uuid::new_v4().to_string();
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(proposal["fields"]["accountId"].as_str().unwrap())
            .unwrap();
        let capacity: protocol::CapacityProjection =
            serde_json::from_value(review["capacityProjection"].clone()).unwrap();
        let now = control.time.status(workspace_id).unwrap().wall_clock;
        let attempt = protocol::ExecutionAttempt {
            attempt_id: attempt_id.clone(),
            workspace_id: workspace_id.into(),
            approval_id: approval["data"]["approvalId"].as_str().unwrap().into(),
            operation: protocol::FinancialOperation::PlaceOrder,
            intent_id: proposal["proposalId"].as_str().unwrap().into(),
            intent_hash: proposal["proposalHash"].as_str().unwrap().into(),
            proposal_id: Some(proposal["proposalId"].as_str().unwrap().into()),
            broker_order_id: None,
            provider_client_order_id: Some(
                provider_io::binance_live_client_order_id(&attempt_id).unwrap(),
            ),
            provider_status: None,
            trading212_live_order_observation: None,
            binance_live_order_observation: None,
            bitget_live_order_observation: None,
            error_code: None,
            dispatch_disposition: None,
            account_id: account.connection_id.clone(),
            environment: protocol::ExecutionContext::BinanceLive,
            policy_version: approval["data"]["policyVersion"].as_u64().unwrap(),
            risk_decision_id: review["riskDecision"]["decisionId"]
                .as_str()
                .unwrap()
                .into(),
            review_digest: review["reviewDigest"].as_str().unwrap().into(),
            account_state_version: account.state_version.clone(),
            intent_state_version: proposal["stateVersion"].as_str().unwrap().into(),
            reservation_id: Some(reservation_id.clone()),
            state: protocol::ExecutionAttemptState::Reserved,
            invalidation_reason: None,
            created_at: now.clone(),
            dispatch_started_at: None,
            state_version: String::new(),
        };
        let reservation = protocol::ExecutionReservation {
            reservation_id,
            workspace_id: workspace_id.into(),
            account_id: account.connection_id.clone(),
            attempt_id: attempt_id.clone(),
            proposal_id: proposal["proposalId"].as_str().unwrap().into(),
            proposal_hash: proposal["proposalHash"].as_str().unwrap().into(),
            instrument_id: proposal["fields"]["instrumentId"].as_str().unwrap().into(),
            side: protocol::OrderSide::Buy,
            capacity_key: "cash:USDT".into(),
            amount: capacity.requested_amount.clone().unwrap(),
            unit: capacity.unit.clone(),
            notional: review["expectedSpend"].as_str().unwrap_or("500").into(),
            notional_currency: "USDT".into(),
            workspace_notional: Some("500".into()),
            workspace_currency: "USD".into(),
            broker_available: capacity.available.clone().unwrap(),
            existing_reservations: "0".into(),
            effective_available: capacity.effective_available.clone().unwrap(),
            capacity_projection: Some(capacity),
            account_state_version: account.state_version.clone(),
            status: protocol::ExecutionReservationStatus::Active,
            created_at: now.clone(),
            state_version: String::new(),
        };
        let (_preparation, events) = control
            .store
            .as_mut()
            .unwrap()
            .prepare_live_place(
                approval["data"]["approvalId"].as_str().unwrap(),
                approval["data"]["stateVersion"].as_str().unwrap(),
                "binance-live-unknown-resolution",
                &account.state_version,
                proposal["stateVersion"].as_str().unwrap(),
                review["reviewDigest"].as_str().unwrap(),
                attempt,
                reservation,
                &now,
            )
            .unwrap();
        for event in &events {
            control.publish(event);
        }
        let grant = control
            .issue_live_dispatch_grant(&attempt_id, "resolution-gateway")
            .unwrap();
        control
            .begin_live_execution_submission(&grant.grant_id, "resolution-gateway")
            .unwrap();
        let stale_attempt_state_version = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_attempt(workspace_id, &attempt_id)
            .unwrap()
            .attempt
            .state_version
            .clone();
        assert_eq!(
            control
                .complete_live_execution_submission(
                    &attempt_id,
                    &provider_io::LiveDispatchOutcome {
                        state: protocol::ExecutionAttemptState::UnknownReconciling,
                        broker_order_id: None,
                        provider_status: None,
                        error_code: Some("ORDER_STATUS_UNKNOWN".into()),
                    },
                )
                .unwrap()
                .attempt
                .state,
            protocol::ExecutionAttemptState::UnknownReconciling
        );
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(proposal["fields"]["accountId"].as_str().unwrap())
            .unwrap();
        (attempt_id, account, stale_attempt_state_version)
    }

