    #[test]
    fn approval_ttl_rejects_expired_gateway_grant_and_releases_reserved_capacity() {
        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        let (approval, _, prepared) = issue_and_prepare_live_place(
            &mut control,
            &workspace_id,
            &proposal,
            &review,
            "approval-ttl-release",
        );
        let attempt_id = prepared["data"]["attempt"]["attemptId"].as_str().unwrap();
        let grant = control
            .issue_live_dispatch_grant(attempt_id, "gateway-session")
            .unwrap();
        assert_eq!(
            grant.expires_at,
            approval["data"]["expiresAt"].as_str().unwrap()
        );
        advance_test_time_past_approval(
            &mut control,
            &workspace_id,
            approval["data"]["expiresAt"].as_str().unwrap(),
        );
        assert_eq!(
            control
                .begin_live_execution_submission(&grant.grant_id, "gateway-session")
                .unwrap_err()
                .code,
            "EXECUTION_DISPATCH_NOT_READY"
        );
        control.expire_live_arming().unwrap();
        let stopped = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            stopped.attempt.attempt_id,
            prepared["data"]["attempt"]["attemptId"]
        );
        assert_eq!(
            stopped.attempt.state,
            protocol::ExecutionAttemptState::Invalidated
        );
        assert_eq!(
            stopped.attempt.invalidation_reason.as_deref(),
            Some("APPROVAL_EXPIRED")
        );
        assert_eq!(
            stopped.reservation.as_ref().unwrap().status,
            protocol::ExecutionReservationStatus::Released
        );
        assert!(
            control
                .store
                .as_ref()
                .unwrap()
                .active_execution_reservations(&workspace_id)
                .unwrap()
                .is_empty()
        );
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({"workspaceId":workspace_id,"proposalId":proposal["proposalId"]}),
        );
        assert_eq!(approval_history["ok"], true, "{approval_history}");
        assert_eq!(
            approval_history["data"]["approvals"][0]["status"],
            "CONSUMED"
        );

        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        let issued = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &proposal, &review),
        );
        assert_eq!(issued["ok"], true, "{issued}");
        let prepare_request = json!({
            "workspaceId": workspace_id,
            "approvalId": issued["data"]["approvalId"],
            "expectedApprovalStateVersion": issued["data"]["stateVersion"],
            "idempotencyKey": "prepare-after-expiry",
            "confirmed": true,
        });
        advance_test_time_past_approval(
            &mut control,
            &workspace_id,
            issued["data"]["expiresAt"].as_str().unwrap(),
        );
        let late = dispatch_main(&mut control, "trade.execution.prepare", prepare_request);
        assert_eq!(late["ok"], false, "{late}");
        assert_eq!(late["error"]["code"], "STATE_VERSION_CONFLICT", "{late}");
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({"workspaceId":workspace_id,"proposalId":proposal["proposalId"]}),
        );
        assert_eq!(
            approval_history["data"]["approvals"][0]["status"],
            "EXPIRED"
        );
        assert!(
            control
                .store
                .as_ref()
                .unwrap()
                .active_execution_reservations(&workspace_id)
                .unwrap()
                .is_empty()
        );
    }

    pub(super) fn reviewed_live_capacity_fixture() -> (
        tempfile::TempDir,
        ControlPlane,
        String,
        AccountConnection,
        Value,
        Value,
    ) {
        reviewed_live_capacity_fixture_with_available("1000")
    }

    fn reviewed_live_capacity_fixture_with_available(
        broker_available: &str,
    ) -> (
        tempfile::TempDir,
        ControlPlane,
        String,
        AccountConnection,
        Value,
        Value,
    ) {
        let folder = tempfile::tempdir().unwrap();
        let mut control = ControlPlane::new(folder.path().to_path_buf());
        control.enable_live_approval_fixture();
        let opened = dispatch(
            &mut control,
            "workspace.open",
            json!({"baseCurrency":"USD"}),
        );
        assert_eq!(opened["ok"], true, "{opened}");
        let workspace_id = opened["data"]["workspaceId"].as_str().unwrap().to_owned();
        let seeded = control
            .seed_live_arming_fixture(&workspace_id, "trading212", "capacity fixture")
            .unwrap();
        let mut account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        account.data.as_mut().unwrap().balances = vec![Balance {
            asset: "USD".into(),
            available: broker_available.into(),
            total: Some(broker_available.into()),
            reserved: Some("0".into()),
            in_pies: None,
            locked: None,
            restricted_available: None,
        }];
        account.last_successful_sync = Some(control.time.status(&workspace_id).unwrap().wall_clock);
        control
            .store
            .as_mut()
            .unwrap()
            .save_account(account)
            .unwrap();
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        let _earlier_proposal = live_proposal(&mut control, &workspace_id, &account);
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        let proposal = live_proposal(&mut control, &workspace_id, &account);
        let review = dispatch_main(
            &mut control,
            "trade.request_approval",
            json!({
                "workspaceId": workspace_id,
                "proposalId": proposal["proposalId"],
            }),
        );
        assert_eq!(review["ok"], true, "{review}");
        assert_eq!(review["data"]["eligible"], true, "{review}");
        (
            folder,
            control,
            workspace_id,
            account,
            proposal,
            review["data"].clone(),
        )
    }

    fn refresh_live_order_settlement(
        control: &mut ControlPlane,
        workspace_id: &str,
        account_id: &str,
        settlement: provider_io::LiveOrderObservation,
    ) -> Value {
        let account = control.store.as_ref().unwrap().account(account_id).unwrap();
        let job = control
            .prepare_provider_for(
                &request(
                    "account.refresh",
                    json!({
                        "workspaceId": workspace_id,
                        "connectionId": account_id,
                        "expectedStateVersion": account.state_version,
                    }),
                ),
                "main",
            )
            .unwrap()
            .unwrap();
        let result = control.complete_provider(
            &job,
            provider_io::ProviderOutcome {
                observation: Some(provider_io::Observation {
                    data: account.data.clone().unwrap(),
                    permissions: account.permissions.clone(),
                    live_order_settlements: vec![settlement],
                }),
                error: None,
                credential: "CONFIGURED".into(),
                trading212_demo_attempt: None,
                trading212_demo_order_book: None,
                alpaca_paper_attempt: None,
                alpaca_paper_order_book: None,
                binance_testnet_attempt: None,
                binance_testnet_order_book: None,
                bitget_demo_attempt: None,
                resolution_evidence: None,
            },
        );
        assert_eq!(result["ok"], true, "{result}");
        result
    }

    #[test]
    fn live_order_fill_settlement_reduces_capacity_and_releases_terminal_remainder_once() {
        let (folder, mut control, workspace_id, account, proposal, review) =
            reviewed_live_capacity_fixture();
        let (approval, _, prepared) = issue_and_prepare_live_place(
            &mut control,
            &workspace_id,
            &proposal,
            &review,
            "s26-live-fill-settlement",
        );
        let attempt_id = prepared["data"]["attempt"]["attemptId"].as_str().unwrap();
        let reservation_id = prepared["data"]["reservation"]["reservationId"]
            .as_str()
            .unwrap();
        let original_amount = prepared["data"]["reservation"]["amount"]
            .as_str()
            .unwrap()
            .to_owned();
        let grant = control
            .issue_live_dispatch_grant(attempt_id, "s26-gateway")
            .unwrap();
        control
            .begin_live_execution_submission(&grant.grant_id, "s26-gateway")
            .unwrap();
        control
            .complete_live_execution_submission(
                attempt_id,
                &provider_io::LiveDispatchOutcome {
                    state: protocol::ExecutionAttemptState::Accepted,
                    broker_order_id: Some("7000000000".into()),
                    provider_status: Some("NEW".into()),
                    error_code: None,
                },
            )
            .unwrap();

        let first_at = storage::timestamp().unwrap();
        let partial = provider_io::LiveOrderObservation {
            provider_order_id: "7000000000".into(),
            raw_status: "PARTIALLY_FILLED".into(),
            disposition: protocol::LiveOrderDisposition::Working,
            order_quantity: None,
            filled_quantity: Some("1".into()),
            remaining_quantity: None,
            filled_value: Some("100".into()),
            fees: Some(vec![protocol::LiveOrderFee {
                asset: "USD".into(),
                amount: "0.25".into(),
            }]),
            trade_facts_complete: true,
            trade_facts: vec![protocol::LiveOrderTradeFact {
                provider_trade_id: "trade-1".into(),
                quantity: "1".into(),
                value: "100".into(),
                fees: vec![protocol::LiveOrderFee {
                    asset: "USD".into(),
                    amount: "0.25".into(),
                }],
                provider_executed_at: None,
            }],
            provider_observed_at: Some(first_at.clone()),
            source: "fixture.live.orders".into(),
        };
        refresh_live_order_settlement(
            &mut control,
            &workspace_id,
            &account.connection_id,
            partial.clone(),
        );
        let after_partial = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            after_partial.reservation.as_ref().unwrap().amount,
            crate::provider_io::decimal_subtract(&original_amount, "100.25").unwrap()
        );
        let partial_sequence = after_partial
            .reservation
            .as_ref()
            .unwrap()
            .state_version
            .clone();

        refresh_live_order_settlement(
            &mut control,
            &workspace_id,
            &account.connection_id,
            partial.clone(),
        );
        let duplicate = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            duplicate.reservation.as_ref().unwrap().state_version,
            partial_sequence
        );
        assert_eq!(
            duplicate.attempt.provider_status.as_deref(),
            Some("PARTIALLY_FILLED")
        );

        let stale_at = (OffsetDateTime::parse(&first_at, &Rfc3339).unwrap()
            - TimeDuration::seconds(1))
        .format(&Rfc3339)
        .unwrap();
        let mut stale = partial.clone();
        stale.raw_status = "NEW".into();
        stale.filled_quantity = Some("0.5".into());
        stale.filled_value = Some("50".into());
        stale.fees = Some(vec![protocol::LiveOrderFee {
            asset: "USD".into(),
            amount: "0.12".into(),
        }]);
        stale.trade_facts_complete = false;
        stale.trade_facts.clear();
        stale.provider_observed_at = Some(stale_at);
        refresh_live_order_settlement(&mut control, &workspace_id, &account.connection_id, stale);
        let after_stale = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            after_stale.reservation.as_ref().unwrap().state_version,
            partial_sequence
        );
        assert_eq!(
            after_stale.attempt.provider_status.as_deref(),
            Some("PARTIALLY_FILLED")
        );

        let incomplete_at = (OffsetDateTime::parse(&first_at, &Rfc3339).unwrap()
            + TimeDuration::seconds(1))
        .format(&Rfc3339)
        .unwrap();
        refresh_live_order_settlement(
            &mut control,
            &workspace_id,
            &account.connection_id,
            provider_io::LiveOrderObservation {
                provider_order_id: "7000000000".into(),
                raw_status: "CANCELED".into(),
                disposition: protocol::LiveOrderDisposition::Terminal,
                order_quantity: None,
                filled_quantity: Some("1".into()),
                remaining_quantity: None,
                filled_value: Some("100".into()),
                fees: None,
                trade_facts_complete: false,
                trade_facts: Vec::new(),
                provider_observed_at: Some(incomplete_at),
                source: "fixture.live.orders".into(),
            },
        );
        let incomplete = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            incomplete.live_order_settlement.as_ref().unwrap().status,
            protocol::LiveOrderSettlementStatus::Incomplete
        );
        assert_eq!(
            incomplete
                .live_order_settlement
                .as_ref()
                .unwrap()
                .unresolved_reason
                .as_deref(),
            Some("FEE_EVIDENCE_INCOMPLETE")
        );
        assert!(
            !incomplete
                .live_order_settlement
                .as_ref()
                .unwrap()
                .fees_complete
        );
        assert_eq!(
            incomplete.reservation.as_ref().unwrap().status,
            protocol::ExecutionReservationStatus::Active
        );
        assert_eq!(
            incomplete.reservation.as_ref().unwrap().amount,
            crate::provider_io::decimal_subtract(&original_amount, "100.25").unwrap()
        );

        let terminal_at = (OffsetDateTime::parse(&first_at, &Rfc3339).unwrap()
            + TimeDuration::seconds(2))
        .format(&Rfc3339)
        .unwrap();
        let terminal_observation = provider_io::LiveOrderObservation {
            provider_order_id: "7000000000".into(),
            raw_status: "CANCELED".into(),
            disposition: protocol::LiveOrderDisposition::Terminal,
            order_quantity: None,
            filled_quantity: Some("1".into()),
            remaining_quantity: None,
            filled_value: Some("100".into()),
            fees: Some(vec![protocol::LiveOrderFee {
                asset: "USD".into(),
                amount: "0.25".into(),
            }]),
            trade_facts_complete: true,
            trade_facts: vec![protocol::LiveOrderTradeFact {
                provider_trade_id: "trade-1".into(),
                quantity: "1".into(),
                value: "100".into(),
                fees: vec![protocol::LiveOrderFee {
                    asset: "USD".into(),
                    amount: "0.25".into(),
                }],
                provider_executed_at: None,
            }],
            provider_observed_at: Some(terminal_at),
            source: "fixture.live.orders".into(),
        };
        refresh_live_order_settlement(
            &mut control,
            &workspace_id,
            &account.connection_id,
            terminal_observation.clone(),
        );
        let terminal = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            terminal.reservation.as_ref().unwrap().status,
            protocol::ExecutionReservationStatus::Released
        );
        assert_eq!(
            terminal.reservation.as_ref().unwrap().amount,
            crate::provider_io::decimal_subtract(&original_amount, "100.25").unwrap()
        );
        assert!(
            control
                .store
                .as_ref()
                .unwrap()
                .active_execution_reservations(&workspace_id)
                .unwrap()
                .iter()
                .all(|reservation| reservation.reservation_id != reservation_id)
        );
        let terminal_sequence = terminal
            .live_order_settlement
            .as_ref()
            .unwrap()
            .state_version
            .clone();
        refresh_live_order_settlement(
            &mut control,
            &workspace_id,
            &account.connection_id,
            terminal_observation,
        );
        let after_terminal_duplicate = control
            .store
            .as_mut()
            .unwrap()
            .snapshot_for("execution-reservation", reservation_id)
            .unwrap();
        assert_eq!(after_terminal_duplicate.last_sequence, 3);
        let settlement_snapshot = control
            .store
            .as_mut()
            .unwrap()
            .snapshot_for("live-order-settlement", attempt_id)
            .unwrap();
        assert_eq!(settlement_snapshot.last_sequence, 3);
        let terminal_again = control
            .store
            .as_ref()
            .unwrap()
            .execution_preparation_for_approval(
                &workspace_id,
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            terminal_again
                .live_order_settlement
                .as_ref()
                .unwrap()
                .state_version,
            terminal_sequence
        );
        assert_eq!(
            terminal_again.attempt.provider_status.as_deref(),
            Some("CANCELED")
        );

        drop(control);
        let mut reopened = ControlPlane::new(folder.path().to_path_buf());
        let reopened_workspace = dispatch(&mut reopened, "workspace.open", json!({}));
        assert_eq!(reopened_workspace["ok"], true, "{reopened_workspace}");
        let saved = dispatch_main(
            &mut reopened,
            "trade.execution.preparation.get",
            json!({
                "workspaceId": workspace_id,
                "approvalId": approval["data"]["approvalId"],
            }),
        );
        assert_eq!(saved["ok"], true, "{saved}");
        assert_eq!(
            saved["data"]["preparation"]["liveOrderSettlement"]["status"],
            "SETTLED"
        );
        assert_eq!(
            saved["data"]["preparation"]["liveOrderSettlement"]["providerOrderId"],
            "7000000000"
        );
    }

    fn add_capacity_account(
        control: &mut ControlPlane,
        workspace_id: &str,
    ) -> (AccountConnection, Value) {
        let seeded = control
            .seed_live_arming_fixture(workspace_id, "trading212", "second capacity fixture")
            .unwrap();
        let mut account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        account.data.as_mut().unwrap().balances = vec![Balance {
            asset: "USD".into(),
            available: "1000".into(),
            total: Some("1000".into()),
            reserved: Some("0".into()),
            in_pies: None,
            locked: None,
            restricted_available: None,
        }];
        account.last_successful_sync = Some(control.time.status(workspace_id).unwrap().wall_clock);
        control
            .store
            .as_mut()
            .unwrap()
            .save_account(account)
            .unwrap();
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        let armed = dispatch_main(
            control,
            "account.arm",
            json!({
                "workspaceId": workspace_id,
                "connectionId": account.connection_id,
                "expectedStateVersion": account.state_version,
                "confirmed": true,
            }),
        );
        assert_eq!(armed["ok"], true, "{armed}");
        let account = control
            .store
            .as_ref()
            .unwrap()
            .account(&seeded.connection_id)
            .unwrap();
        let proposal = live_proposal(control, workspace_id, &account);
        (account, proposal)
    }

    fn assert_policy_prepare_order(preparation_first: bool) {
        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        let approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &proposal, &review),
        );
        assert_eq!(approval["ok"], true, "{approval}");
        let prepare = prepare_payload(
            &workspace_id,
            &approval["data"],
            if preparation_first {
                "concurrent-prepare-before-policy"
            } else {
                "concurrent-policy-before-prepare"
            },
        );
        let current = dispatch_main(
            &mut control,
            "risk.get_policy",
            json!({"workspaceId":workspace_id}),
        );
        let mut policy = current["data"]["policy"].clone();
        let threshold = policy["staleQuoteThresholdSeconds"].as_u64().unwrap_or(120);
        policy["staleQuoteThresholdSeconds"] = threshold.saturating_sub(1).max(1).into();
        let save_policy = json!({
            "workspaceId": workspace_id,
            "expectedStateVersion": current["data"]["stateVersion"],
            "policy": policy,
        });
        let control = Arc::new(Mutex::new(control));
        let (first, second) = if preparation_first {
            dispatch_barrier_pair_in_order(
                control.clone(),
                ("trade.execution.prepare", prepare),
                ("risk.save_policy", save_policy),
            )
        } else {
            dispatch_barrier_pair_in_order(
                control.clone(),
                ("risk.save_policy", save_policy),
                ("trade.execution.prepare", prepare),
            )
        };
        let (prepared, saved) = if preparation_first {
            (&first, &second)
        } else {
            (&second, &first)
        };
        assert_eq!(saved["ok"], true, "{saved}");
        let mut control = control.lock().unwrap();
        let query = dispatch_main(
            &mut control,
            "trade.execution.preparation.get",
            json!({
                "workspaceId":workspace_id,
                "approvalId":approval["data"]["approvalId"],
            }),
        );
        assert_eq!(query["ok"], true, "{query}");
        if preparation_first {
            assert_eq!(prepared["ok"], true, "{prepared}");
            assert_eq!(
                query["data"]["preparation"]["attempt"]["state"],
                "INVALIDATED"
            );
            assert_eq!(
                query["data"]["preparation"]["attempt"]["invalidationReason"],
                "RISK_POLICY_CHANGED"
            );
            assert_eq!(
                query["data"]["preparation"]["reservation"]["status"],
                "RELEASED"
            );
        } else {
            assert_eq!(prepared["ok"], false, "{prepared}");
            assert_eq!(prepared["error"]["code"], "STATE_VERSION_CONFLICT");
            assert_eq!(query["data"]["preparation"], Value::Null);
            let history = dispatch_main(
                &mut control,
                "trade.approval.list",
                json!({
                    "workspaceId":workspace_id,
                    "proposalId":proposal["proposalId"],
                }),
            );
            assert_eq!(history["data"]["approvals"][0]["status"], "INVALIDATED");
        }
        assert!(
            control
                .store
                .as_ref()
                .unwrap()
                .active_execution_reservations(&workspace_id)
                .unwrap()
                .is_empty()
        );
    }

    #[test]
    fn concurrent_live_place_preparations_isolate_account_capacity() {
        let (_folder, mut control, workspace_id, first_account, first_proposal, _) =
            reviewed_live_capacity_fixture_with_available("500");
        let second_proposal = live_proposal(&mut control, &workspace_id, &first_account);
        let (second_account, third_proposal) = add_capacity_account(&mut control, &workspace_id);
        let first_review = dispatch_main(
            &mut control,
            "trade.request_approval",
            json!({"workspaceId":workspace_id,"proposalId":first_proposal["proposalId"]}),
        );
        let second_review = dispatch_main(
            &mut control,
            "trade.request_approval",
            json!({"workspaceId":workspace_id,"proposalId":second_proposal["proposalId"]}),
        );
        let third_review = dispatch_main(
            &mut control,
            "trade.request_approval",
            json!({"workspaceId":workspace_id,"proposalId":third_proposal["proposalId"]}),
        );
        for review in [&first_review, &second_review, &third_review] {
            assert_eq!(review["ok"], true, "{review}");
            assert_eq!(review["data"]["eligible"], true, "{review}");
        }
        let first_approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &first_proposal, &first_review["data"]),
        );
        let second_approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &second_proposal, &second_review["data"]),
        );
        let third_approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &third_proposal, &third_review["data"]),
        );
        for approval in [&first_approval, &second_approval, &third_approval] {
            assert_eq!(approval["ok"], true, "{approval}");
        }
        let shared = Arc::new(Mutex::new(control));
        let results = dispatch_barrier_concurrently(
            shared.clone(),
            vec![
                (
                    "trade.execution.prepare",
                    prepare_payload(&workspace_id, &first_approval["data"], "same-account-one"),
                ),
                (
                    "trade.execution.prepare",
                    prepare_payload(&workspace_id, &second_approval["data"], "same-account-two"),
                ),
                (
                    "trade.execution.prepare",
                    prepare_payload(&workspace_id, &third_approval["data"], "other-account-one"),
                ),
            ],
        );
        assert_eq!(
            results[..2]
                .iter()
                .filter(|result| result["ok"] == true)
                .count(),
            1,
            "only one $500 request fits in the first account's $500 capacity: {results:?}"
        );
        assert_eq!(results[2]["ok"], true, "{results:?}");
        let rejected = results[..2]
            .iter()
            .find(|result| result["ok"] == false)
            .unwrap();
        assert_eq!(rejected["error"]["code"], "RISK_REJECTED", "{rejected}");
        assert_eq!(
            rejected["error"]["capacityContext"]["effectiveAvailable"],
            "0"
        );
        let winner = results[..2]
            .iter()
            .find(|result| result["ok"] == true)
            .unwrap();
        assert_eq!(winner["data"]["attempt"]["state"], "RESERVED");
        assert_eq!(
            winner["data"]["reservation"]["accountId"],
            first_account.connection_id
        );
        assert_eq!(winner["data"]["reservation"]["effectiveAvailable"], "0");
        assert_eq!(
            results[2]["data"]["reservation"]["accountId"],
            second_account.connection_id
        );
        assert_eq!(
            results[2]["data"]["reservation"]["existingReservations"],
            "0"
        );
        assert_eq!(
            results[2]["data"]["reservation"]["effectiveAvailable"],
            "500"
        );

        let rejected_index = results[..2]
            .iter()
            .position(|result| result["ok"] == false)
            .unwrap();
        let rejected_approval = [&first_approval, &second_approval][rejected_index];
        let rejected_proposal = [&first_proposal, &second_proposal][rejected_index];
        let mut control = shared.lock().unwrap();
        let rejection_history = dispatch_main(
            &mut control,
            "trade.execution.preparation.get",
            json!({
                "workspaceId":workspace_id,
                "approvalId":rejected_approval["data"]["approvalId"],
            }),
        );
        assert_eq!(rejection_history["ok"], true, "{rejection_history}");
        assert_eq!(rejection_history["data"]["preparation"], Value::Null);
        assert_eq!(
            rejection_history["data"]["rejections"][0]["reason"],
            "RESERVED_CAPACITY"
        );
        assert_eq!(
            rejection_history["data"]["rejections"][0]["capacityContext"]["effectiveAvailable"],
            "0"
        );
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({
                "workspaceId":workspace_id,
                "proposalId":rejected_proposal["proposalId"],
            }),
        );
        assert_eq!(approval_history["ok"], true, "{approval_history}");
        assert_eq!(approval_history["data"]["approvals"][0]["status"], "ISSUED");
        let proposal_state = dispatch_main(
            &mut control,
            "trade.proposal.get",
            json!({
                "workspaceId":workspace_id,
                "proposalId":rejected_proposal["proposalId"],
            }),
        );
        assert_eq!(proposal_state["ok"], true, "{proposal_state}");
        assert_eq!(proposal_state["data"]["status"], "NEEDS_APPROVAL");

        let reservations = control
            .store
            .as_ref()
            .unwrap()
            .active_execution_reservations(&workspace_id)
            .unwrap();
        assert_eq!(reservations.len(), 2);
        assert_eq!(
            reservations
                .iter()
                .filter(|r| r.account_id == first_account.connection_id)
                .count(),
            1
        );
        assert_eq!(
            reservations
                .iter()
                .filter(|r| r.account_id == second_account.connection_id)
                .count(),
            1
        );
    }

    #[test]
    fn concurrent_policy_save_and_preparation_obey_both_serial_orders() {
        assert_policy_prepare_order(false);
        assert_policy_prepare_order(true);
    }

    #[test]
    fn interrupted_live_place_preparation_rolls_back_and_retries_idempotently() {
        let (folder, mut control, workspace_id, account, proposal, review) =
            reviewed_live_capacity_fixture();
        let approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &proposal, &review),
        );
        assert_eq!(approval["ok"], true, "{approval}");
        let approval_id = approval["data"]["approvalId"].as_str().unwrap();
        let proposal_id = proposal["proposalId"].as_str().unwrap();
        let prepare = prepare_payload(
            &workspace_id,
            &approval["data"],
            "retry-after-sqlite-failure",
        );
        let database_path = folder.path().join("workspace.sqlite3");
        let database = rusqlite::Connection::open(&database_path).unwrap();
        database
            .execute_batch(
                "CREATE TRIGGER fail_s23_attempt_outbox
                 BEFORE INSERT ON outbox
                 WHEN NEW.aggregate_type='execution-attempt'
                 BEGIN SELECT RAISE(ABORT, 'injected S23 transaction failure'); END;",
            )
            .unwrap();

        let provider_job = control
            .prepare_provider_for(&request("trade.execution.prepare", prepare.clone()), "main")
            .unwrap();
        assert!(
            provider_job.is_none(),
            "preparation must not dispatch to a provider"
        );
        let failed = dispatch_main(&mut control, "trade.execution.prepare", prepare.clone());
        assert_eq!(failed["ok"], false, "{failed}");
        assert_eq!(failed["error"]["code"], "WORKSPACE_OPEN_FAILED");
        database
            .execute_batch("DROP TRIGGER fail_s23_attempt_outbox;")
            .unwrap();
        drop(database);

        reopen_store(&mut control);
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({"workspaceId":workspace_id,"proposalId":proposal_id}),
        );
        assert_eq!(approval_history["data"]["approvals"][0]["status"], "ISSUED");
        let proposal_state = dispatch_main(
            &mut control,
            "trade.proposal.get",
            json!({"workspaceId":workspace_id,"proposalId":proposal_id}),
        );
        assert_eq!(proposal_state["data"]["status"], "NEEDS_APPROVAL");
        assert_ne!(
            proposal_state["data"]["history"]
                .as_array()
                .unwrap()
                .last()
                .unwrap()["event"],
            "CONSUMED"
        );
        let preparation = dispatch_main(
            &mut control,
            "trade.execution.preparation.get",
            json!({"workspaceId":workspace_id,"approvalId":approval_id}),
        );
        assert_eq!(preparation["data"]["preparation"], Value::Null);
        assert_eq!(preparation["data"]["rejections"], json!([]));
        let database = rusqlite::Connection::open(&database_path).unwrap();
        for (query, identity) in [
            (
                "SELECT COUNT(*) FROM execution_attempts WHERE approval_id=?1",
                approval_id,
            ),
            (
                "SELECT COUNT(*) FROM execution_reservations WHERE account_id=(SELECT account_id FROM financial_approvals WHERE approval_id=?1)",
                approval_id,
            ),
            (
                "SELECT COUNT(*) FROM order_proposal_events WHERE proposal_id=?1 AND event='CONSUMED'",
                proposal_id,
            ),
        ] {
            let count: i64 = database
                .query_row(query, [identity], |row| row.get(0))
                .unwrap();
            assert_eq!(count, 0, "{query}");
        }
        for (aggregate_type, aggregate_id, event_type) in [
            ("financial-approval", approval_id, "trade.approval.consumed"),
            (
                "order-proposal-consumption",
                proposal_id,
                "trade.proposal.consumed",
            ),
        ] {
            let count: i64 = database
                .query_row(
                    "SELECT COUNT(*) FROM outbox WHERE aggregate_type=?1 AND aggregate_id=?2 AND json_extract(envelope,'$.eventType')=?3",
                    rusqlite::params![aggregate_type, aggregate_id, event_type],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(count, 0, "{event_type} must roll back");
        }
        let approval_audit_count: i64 = database
            .query_row(
                "SELECT COUNT(*) FROM approval_rejections WHERE proposal_id=?1",
                [proposal_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(approval_audit_count, 0, "approval audit must roll back");
        let approval_audit_events: i64 = database
            .query_row(
                "SELECT COUNT(*) FROM outbox WHERE aggregate_type='approval-audit' AND aggregate_id=?1",
                [proposal_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(approval_audit_events, 0);
        let consumed_approvals: i64 = database
            .query_row(
                "SELECT COUNT(*) FROM financial_approvals WHERE approval_id=?1 AND status='CONSUMED'",
                [approval_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(consumed_approvals, 0);
        for aggregate in ["execution-attempt", "execution-reservation"] {
            let count: i64 = database
                .query_row(
                    "SELECT COUNT(*) FROM outbox WHERE aggregate_type=?1",
                    [aggregate],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(count, 0, "{aggregate} outbox must roll back");
        }
        drop(database);

        let retried = dispatch_main(&mut control, "trade.execution.prepare", prepare.clone());
        assert_eq!(retried["ok"], true, "{retried}");
        assert_eq!(retried["data"]["attempt"]["state"], "RESERVED");
        let replayed = dispatch_main(&mut control, "trade.execution.prepare", prepare);
        assert_eq!(replayed["ok"], true, "{replayed}");
        assert_eq!(
            replayed["data"]["attempt"]["attemptId"],
            retried["data"]["attempt"]["attemptId"]
        );
        assert_eq!(
            control
                .store
                .as_ref()
                .unwrap()
                .active_execution_reservations(&workspace_id)
                .unwrap()
                .len(),
            1
        );
        reopen_store(&mut control);
        let recovered = dispatch_main(
            &mut control,
            "trade.execution.preparation.get",
            json!({"workspaceId":workspace_id,"approvalId":approval_id}),
        );
        assert_eq!(
            recovered["data"]["preparation"]["attempt"]["state"],
            "RESERVED"
        );
        assert_eq!(
            recovered["data"]["preparation"]["attempt"]["attemptId"],
            retried["data"]["attempt"]["attemptId"]
        );
        let recovered_preparation = &recovered["data"]["preparation"];
        let attempt_id = recovered_preparation["attempt"]["attemptId"]
            .as_str()
            .unwrap();
        let reservation_id = recovered_preparation["reservation"]["reservationId"]
            .as_str()
            .unwrap();
        assert_eq!(recovered_preparation["attempt"]["state"], "RESERVED");
        assert_eq!(recovered_preparation["reservation"]["status"], "ACTIVE");
        assert_eq!(
            recovered_preparation["reservation"]["accountId"],
            account.connection_id
        );
        assert_eq!(recovered_preparation["reservation"]["amount"], "500");
        assert_eq!(
            recovered_preparation["reservation"]["effectiveAvailable"],
            "500"
        );
        assert_eq!(
            recovered_preparation["reservation"]["capacityProjection"]["reserved"],
            "500"
        );
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({
                "workspaceId":workspace_id,
                "proposalId":proposal_id,
            }),
        );
        assert_eq!(approval_history["ok"], true, "{approval_history}");
        assert_eq!(
            approval_history["data"]["approvals"][0]["status"],
            "CONSUMED"
        );
        let proposal_state = dispatch_main(
            &mut control,
            "trade.proposal.get",
            json!({"workspaceId":workspace_id,"proposalId":proposal_id}),
        );
        assert_eq!(proposal_state["ok"], true, "{proposal_state}");
        assert_eq!(proposal_state["data"]["status"], "CONSUMED");
        let database = rusqlite::Connection::open(&database_path).unwrap();
        let saved_idempotency_key: String = database
            .query_row(
                "SELECT idempotency_key FROM execution_attempts WHERE attempt_id=?1",
                [attempt_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(saved_idempotency_key, "retry-after-sqlite-failure");
        for (aggregate_type, aggregate_id, event_type) in [
            (
                "execution-attempt",
                attempt_id,
                "trade.execution.attempt.changed",
            ),
            (
                "execution-reservation",
                reservation_id,
                "trade.reservation.created",
            ),
        ] {
            let mut statement = database
                .prepare(
                    "SELECT sequence,envelope FROM outbox WHERE aggregate_type=?1 AND aggregate_id=?2 ORDER BY sequence",
                )
                .unwrap();
            let events: Vec<(i64, String)> = statement
                .query_map([aggregate_type, aggregate_id], |row| {
                    Ok((row.get(0)?, row.get(1)?))
                })
                .unwrap()
                .map(|row| row.unwrap())
                .collect();
            assert_eq!(events.len(), 1, "{aggregate_type} outbox");
            assert_eq!(events[0].0, 1, "{aggregate_type} sequence");
            let event: Value = serde_json::from_str(&events[0].1).unwrap();
            assert_eq!(event["eventType"], event_type);
            assert_eq!(event["aggregateId"], aggregate_id);
            assert_eq!(event["sequence"], 1);
        }
    }

    #[test]
    fn live_place_preparation_consumes_approval_once_and_replays_idempotently() {
        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        assert_eq!(review["capacityProjection"]["available"], "1000");
        assert_eq!(review["capacityProjection"]["committed"], "0");
        assert_eq!(review["capacityProjection"]["reserved"], "0");
        assert_eq!(review["capacityProjection"]["effectiveAvailable"], "1000");
        assert_eq!(review["capacityProjection"]["freshness"], "CURRENT");
        assert_eq!(
            review["capacityProjection"]["availableSource"],
            "PROVIDER_BALANCE_AVAILABLE"
        );
        assert_eq!(
            review["capacityProjection"]["accountStateVersion"],
            review["account"]["stateVersion"]
        );
        let approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &proposal, &review),
        );
        assert_eq!(approval["ok"], true, "{approval}");
        let prepare = json!({
            "workspaceId": workspace_id,
            "approvalId": approval["data"]["approvalId"],
            "expectedApprovalStateVersion": approval["data"]["stateVersion"],
            "idempotencyKey": "prepare-live-place-once",
            "confirmed": true,
        });
        let unauthorized = control.dispatch_with_events(
            request("trade.execution.prepare", prepare.clone()),
            "agent",
            None,
        );
        assert_eq!(unauthorized["ok"], false, "{unauthorized}");
        assert_eq!(
            unauthorized["error"]["code"], "IPC_ACCESS_DENIED",
            "{unauthorized}"
        );
        let unconfirmed = dispatch_main(
            &mut control,
            "trade.execution.prepare",
            json!({
                "workspaceId": workspace_id,
                "approvalId": approval["data"]["approvalId"],
                "expectedApprovalStateVersion": approval["data"]["stateVersion"],
                "idempotencyKey": "prepare-live-place-unconfirmed",
                "confirmed": false,
            }),
        );
        assert_eq!(unconfirmed["ok"], false, "{unconfirmed}");
        assert_eq!(
            unconfirmed["error"]["code"], "IPC_PAYLOAD_INVALID",
            "{unconfirmed}"
        );
        let prepared = dispatch_main(&mut control, "trade.execution.prepare", prepare.clone());
        assert_eq!(prepared["ok"], true, "{prepared}");
        assert_eq!(
            prepared["data"]["attempt"]["state"], "RESERVED",
            "{prepared}"
        );
        assert_eq!(
            prepared["data"]["reservation"]["amount"], "500",
            "{prepared}"
        );
        assert_eq!(prepared["data"]["reservation"]["unit"], "USD", "{prepared}");
        assert_eq!(
            prepared["data"]["reservation"]["effectiveAvailable"], "500",
            "{prepared}"
        );
        assert_eq!(
            prepared["data"]["reservation"]["capacityProjection"]["reserved"], "500",
            "{prepared}"
        );
        assert_eq!(
            prepared["data"]["reservation"]["capacityProjection"]["effectiveAvailable"], "500",
            "{prepared}"
        );
        let recovered = dispatch_main(
            &mut control,
            "trade.execution.preparation.get",
            json!({
                "workspaceId": workspace_id,
                "approvalId": approval["data"]["approvalId"],
            }),
        );
        assert_eq!(recovered["ok"], true, "{recovered}");
        assert_eq!(
            recovered["data"]["preparation"]["attempt"]["attemptId"],
            prepared["data"]["attempt"]["attemptId"],
            "{recovered}"
        );
        assert_eq!(
            recovered["data"]["preparation"]["reservation"]["reservationId"],
            prepared["data"]["reservation"]["reservationId"],
            "{recovered}"
        );
        assert_eq!(recovered["data"]["rejections"], json!([]), "{recovered}");
        let replay = dispatch_main(&mut control, "trade.execution.prepare", prepare.clone());
        assert_eq!(replay["ok"], true, "{replay}");
        assert_eq!(
            replay["data"]["attempt"]["attemptId"], prepared["data"]["attempt"]["attemptId"],
            "{replay}"
        );
        let proposal_read = dispatch_main(
            &mut control,
            "trade.proposal.get",
            json!({"workspaceId":workspace_id,"proposalId":proposal["proposalId"]}),
        );
        assert_eq!(proposal_read["ok"], true, "{proposal_read}");
        assert_eq!(
            proposal_read["data"]["status"], "CONSUMED",
            "{proposal_read}"
        );
        assert_eq!(
            proposal_read["data"]["history"]
                .as_array()
                .unwrap()
                .last()
                .unwrap()["event"],
            "CONSUMED",
            "{proposal_read}"
        );
        let approval_history = dispatch_main(
            &mut control,
            "trade.approval.list",
            json!({"workspaceId":workspace_id,"proposalId":proposal["proposalId"]}),
        );
        assert_eq!(approval_history["ok"], true, "{approval_history}");
        assert_eq!(
            approval_history["data"]["approvals"]
                .as_array()
                .unwrap()
                .last()
                .unwrap()["status"],
            "CONSUMED",
            "{approval_history}"
        );
        let approval_snapshot = control
            .store
            .as_mut()
            .unwrap()
            .snapshot_for(
                "financial-approval",
                approval["data"]["approvalId"].as_str().unwrap(),
            )
            .unwrap();
        let DomainProjection::FinancialApproval(saved_approval) = approval_snapshot.projection
        else {
            panic!("wrong approval projection");
        };
        assert_eq!(
            saved_approval.status,
            protocol::FinancialApprovalStatus::Consumed
        );
        let consumed_proposal = control
            .store
            .as_ref()
            .unwrap()
            .order_proposal(proposal["proposalId"].as_str().unwrap())
            .unwrap();
        assert_eq!(
            consumed_proposal.status,
            protocol::OrderProposalStatus::Consumed
        );
        assert_eq!(
            consumed_proposal.history.last().unwrap().event,
            protocol::OrderProposalHistoryEvent::Consumed
        );
        let proposal_consumption = control
            .store
            .as_mut()
            .unwrap()
            .snapshot_for(
                "order-proposal-consumption",
                proposal["proposalId"].as_str().unwrap(),
            )
            .unwrap();
        assert_eq!(proposal_consumption.last_sequence, 1);
        let DomainProjection::OrderProposalConsumption(consumption) =
            proposal_consumption.projection
        else {
            panic!("wrong proposal consumption projection");
        };
        assert_eq!(
            consumption.attempt_id,
            prepared["data"]["attempt"]["attemptId"]
        );
        let deliveries = std::sync::Arc::new(std::sync::Mutex::new(0));
        let delivered = deliveries.clone();
        let sink: EventSink = std::sync::Arc::new(move |event| {
            assert_eq!(event.event_type, "trade.proposal.consumed");
            *delivered.lock().unwrap() += 1;
            true
        });
        let replay = control
            .store
            .as_mut()
            .unwrap()
            .replay(
                "order-proposal-consumption",
                proposal["proposalId"].as_str().unwrap(),
                0,
                &sink,
            )
            .unwrap();
        assert_eq!(replay.replayed_count, 1);
        assert_eq!(*deliveries.lock().unwrap(), 1);
        let second_approval = dispatch_main(
            &mut control,
            "trade.approve",
            approval_action(&workspace_id, &proposal, &review),
        );
        assert_eq!(second_approval["ok"], false, "{second_approval}");
        assert_eq!(
            second_approval["error"]["code"], "STATE_VERSION_CONFLICT",
            "{second_approval}"
        );
        let mut different_key = prepare;
        different_key["idempotencyKey"] = "prepare-live-place-second-key".into();
        let reused = dispatch_main(&mut control, "trade.execution.prepare", different_key);
        assert_eq!(reused["ok"], false, "{reused}");
        assert_eq!(reused["error"]["code"], "APPROVAL_CONSUMED", "{reused}");
    }

    #[test]
    fn live_dispatch_grant_is_one_use_and_bound_to_its_gateway_session() {
        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        let (_, _, prepared) = issue_and_prepare_live_place(
            &mut control,
            &workspace_id,
            &proposal,
            &review,
            "prepare-live-place-for-gateway-grant",
        );
        let attempt_id = prepared["data"]["attempt"]["attemptId"].as_str().unwrap();

        let grant = control
            .issue_live_dispatch_grant(attempt_id, "gateway-session-a")
            .unwrap();
        assert_eq!(grant.status, protocol::ExecutionDispatchGrantStatus::Issued);
        let replay = control
            .issue_live_dispatch_grant(attempt_id, "gateway-session-a")
            .unwrap();
        assert_eq!(replay.grant_id, grant.grant_id);
        assert_eq!(replay.state_version, grant.state_version);

        let wrong_session = control
            .begin_live_execution_submission(&grant.grant_id, "gateway-session-b")
            .unwrap_err();
        assert_eq!(wrong_session.code, "GATEWAY_AUTH_FAILED");

        let restarted_gateway = control
            .issue_live_dispatch_grant(attempt_id, "gateway-session-b")
            .unwrap();
        assert_ne!(restarted_gateway.grant_id, grant.grant_id);
        assert_eq!(
            control
                .store
                .as_ref()
                .unwrap()
                .execution_dispatch_grant(&grant.grant_id)
                .unwrap()
                .status,
            protocol::ExecutionDispatchGrantStatus::Revoked
        );
        assert_eq!(
            control
                .begin_live_execution_submission(&grant.grant_id, "gateway-session-a")
                .unwrap_err()
                .code,
            "EXECUTION_DISPATCH_NOT_READY"
        );

        let submitting = control
            .begin_live_execution_submission(&restarted_gateway.grant_id, "gateway-session-b")
            .unwrap();
        assert_eq!(submitting.attempt_id, attempt_id);
        assert_eq!(
            submitting.state,
            protocol::ExecutionAttemptState::Submitting
        );
        assert_eq!(
            control
                .begin_live_execution_submission(&restarted_gateway.grant_id, "gateway-session-b")
                .unwrap_err()
                .code,
            "EXECUTION_DISPATCH_NOT_READY"
        );
    }

    #[test]
    fn accepted_live_place_persists_trading212_order_identity() {
        let (_folder, mut control, workspace_id, _account, proposal, review) =
            reviewed_live_capacity_fixture();
        let (_, _, prepared) = issue_and_prepare_live_place(
            &mut control,
            &workspace_id,
            &proposal,
            &review,
            "prepare-live-place-for-provider-acceptance",
        );
        let attempt_id = prepared["data"]["attempt"]["attemptId"].as_str().unwrap();
        let grant = control
            .issue_live_dispatch_grant(attempt_id, "gateway-session")
            .unwrap();
        control
            .begin_live_execution_submission(&grant.grant_id, "gateway-session")
            .unwrap();

        let invalid_identity = control
            .complete_live_execution_submission(
                attempt_id,
                &provider_io::LiveDispatchOutcome {
                    state: protocol::ExecutionAttemptState::Accepted,
                    broker_order_id: Some("not-a-trading212-order-id".into()),
                    provider_status: Some("NEW".into()),
                    error_code: None,
                },
            )
            .unwrap_err();
        assert_eq!(invalid_identity.code, "IPC_PAYLOAD_INVALID");

        let accepted = control
            .complete_live_execution_submission(
                attempt_id,
                &provider_io::LiveDispatchOutcome {
                    state: protocol::ExecutionAttemptState::Accepted,
                    broker_order_id: Some("901".into()),
                    provider_status: Some("NEW".into()),
                    error_code: None,
                },
            )
            .unwrap();
        assert_eq!(
            accepted.attempt.state,
            protocol::ExecutionAttemptState::Accepted
        );
        assert_eq!(accepted.attempt.broker_order_id.as_deref(), Some("901"));
        assert_eq!(accepted.attempt.provider_status.as_deref(), Some("NEW"));
        assert_eq!(
            accepted.reservation.as_ref().unwrap().status,
            protocol::ExecutionReservationStatus::Active
        );
    }

