        assert_eq!(cancel_data.open_orders.len(), 1);
        assert_eq!(cancel_data.open_orders[0].broker_order_id, broker_order_id);
        let cancel_book = cancel_data.bitget_order_book.as_ref().unwrap();
        assert_eq!(cancel_book.orders.len(), 1);
